/bin/bash -lc "python3 -B - <<'PY'
import sys,re,collections
sys.path.insert(0,'work')
from solve import Records,many,number
r=Records()
for q in r.questions:
 s=q['question']
 if s.startswith('Trace'):
  d='tdoc:'+re.search(r'R2-\\d+',s).group()
  print('TRACE',number(d),'RAW',r.tdocs[d].get('tdoc:clausesAffected'),'SECTIONS',[r.section_parts(x)[2] for x in r.sections[d]])
 if s.startswith('Which'):
  rel,clause,spec=re.search(r'Which (Rel-\\d+) change requests that modify clause (\\S+) of TS ([\\d.]+)',s).groups()
  exact=[];sub=[];raw_only=[];nonrelease=[]
  for d,sects in r.sections.items():
   x=r.tdocs.get(d,{})
   for sec in sects:
    sp,rl,cl=r.section_parts(sec)
    if sp==spec and rl==rel and (cl==clause or cl.startswith(clause+'.')):
     result=(number(d),cl,len(r.valid_dispositions(d)),list(r.pack_links[d]))
     (exact if cl==clause else sub).append(result)
     if rel not in [r.releases[k] for k in many(x.get('targetRelease'))]: nonrelease.append(result)
  target='tdoc:section/'+spec+'-'+rel+'-'+clause
  for d,x in r.tdocs.items():
   if x.get('tdoc:type')=='CR' and x.get('targetRelease')=='tdoc:release/'+rel.replace('-','_') and 'tdoc:spec/'+spec.replace('.','_') in many(x.get('modifies')) and clause in str(x.get('tdoc:clausesAffected','')) and target not in r.sections[d] and r.valid_dispositions(d) and r.pack_links[d]:
    raw_only.append((number(d),x.get('tdoc:clausesAffected')))
  print('CLAUSE',q['id'],clause,'EXACT',exact,'SUBCLAUSES_WITH_PACK',[(d,c) for d,c,v,p in sub if v and p],'RAW_POSSIBLE_EXTRA',raw_only,'NONRELEASE',nonrelease)
 if s.startswith('TSG'):
  p=re.search(r'RP-\\d+',s).group()
  extras=[];excluded=[]
  for d,links in r.pack_links.items():
   if p not in links: continue
   if 'hasCR' not in links[p]: extras.append(number(d))
   if not r.valid_dispositions(d):
    excluded.append((number(d),[(x['status'],x['scope'],x['code']) for x in r.dispositions[d]]))
  print('PACK',p,'MEMBER_COUNT',len(many(r.packs[p]['hasCR'])),'TDOC_EXTRA',extras,'EXCLUDED',excluded)
PY"

