/bin/bash -lc "python3 -B - <<'PY'
import json,re,sys,collections
sys.path.insert(0,'work')
from solve import Records,many
r=Records()
answers=[json.loads(line) for line in open('answers.jsonl')]
assert len(answers)==len(r.questions)==84
assert [a['id'] for a in answers]==[q['id'] for q in r.questions]
assert len({a['id'] for a in answers})==84
for q,a in zip(r.questions,answers):
 assert set(a)=={'id','rows','note'}
 assert isinstance(a['note'],str)
 assert len(a['rows'])==len({tuple(row) for row in a['rows']})
 for row in a['rows']:
  assert len(row)==len(q['fields']) and all(isinstance(value,str) for value in row)
  values=dict(zip(q['fields'],row))
  for field,value in values.items():
   if field in {'document','final_document'}:
    assert r.tdocs['tdoc:'+value]['tdoc:tdocNumber']==value
   elif field=='wg_meeting':
    assert value in {x['tdoc:meetingNumber'] for x in r.meetings.values()}
   elif field=='cr_pack':
    assert value in r.packs
   elif field=='tsg_meeting':
    assert value in {x['tdoc:tsgMeeting'] for x in r.packs.values()}
   elif field=='disposition':
    assert value in {x['code'] for disp in r.dispositions.values() for x in disp}
   elif field=='clause':
    assert value in {r.section_parts(s)[2] for links in r.sections.values() for s in links}
   else: raise AssertionError(field)
 if q['question'].startswith(('In which','Change request','Trace change request')):
  sentence=q['question']
  doc,cr,spec=re.search(r'(R2-\\d+) \\(CR (\\d+) to TS ([\\d.]+)\\)',sentence).groups()
  record=r.tdocs['tdoc:'+doc]
  assert record['tdoc:crNumber']==cr,(doc,cr,record)
  assert 'tdoc:spec/'+spec.replace('.','_') in many(record['modifies'])
 # In all questions involving membership, the selected document's pack relation
 # is present in both inverse phase-4 relations, independently of list metadata.
 if q['question'].startswith(('Which','RAN2 recorded')):
  for row in a['rows']:
   doc='tdoc:'+row[0]; pack=row[-1]
   assert {'hasCR','belongsToCRPack'}.issubset(r.pack_links[doc][pack])
 if q['question'].startswith('TSG'):
  pack=re.search(r'RP-\\d+',q['question']).group()
  for row in a['rows']:
   assert {'hasCR','belongsToCRPack'}.issubset(r.pack_links['tdoc:'+row[0]][pack])
assert all(a==r.answer(q) for q,a in zip(r.questions,answers))
print('Validated JSON structure, question identities, field counts, string values, row uniqueness, record-backed values, cited CR identities and pack links.')
print('QUESTIONS',len(answers),'ROWS',sum(len(a['rows']) for a in answers),'EMPTY',sum(not a['rows'] for a in answers),'NOTES',sum(bool(a['note']) for a in answers))
print('| ID | Rows | Note |')
print('|---|---:|---|')
for a in answers:
 note='—'
 if not a['rows']: note='No recorded CR-pack membership.'
 elif a['id']=='RAN2-q07d0317e1bd8': note='Excluded R2-1908377: unverified disposition.'
 elif a['id']=='RAN2-q89fecc65f8cf': note='Excluded R2-2313675: no qualifying disposition.'
 elif a['id']=='RAN2-qf4e303df559e': note='Named section; enclosing numbered clause is an alternative.'
 elif a['id']=='RAN2-qfca03806f8a7': note='Excluded R2-1911547 and R2-1911549: no qualifying disposition.'
 print('| '+a['id']+' | '+str(len(a['rows']))+' | '+note+' |')
PY"

